{
  "concepts": [
    {
      "conditions": [],
      "definition": "F16, Engagement baseline, is an operational profile. Its foundation-to-law table traces premises, consequences, owning rules, added choices and pillars; it is not itself an additional rule. The profile owns its additions, not imported law, and states no axiomatic-calculus rule.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 198,
          "quote": "This member is material family F16, Engagement baseline (operational\nprofile).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F3.%20Engagement%20applicability%2FFoundation%20to%20law",
          "start_line": 197
        },
        {
          "end_line": 291,
          "quote": "this profile states no rule of the\na_c calculus and binds none.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F3.%20Engagement%20applicability%2FFoundation%20to%20law",
          "start_line": 290
        }
      ],
      "key": "engagement_baseline",
      "label": "Engagement baseline"
    },
    {
      "conditions": [],
      "definition": "A frame whose evaluation family concerns selecting, constructing, assessing or disposing governed work. Executive, Worker and Reviewer are this profile's engagement frames.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 342,
          "quote": "An engagement frame is a frame (REFERENCE_FRAME §1) whose evaluation family\nconcerns selecting, constructing, assessing or disposing governed work.\nExecutive, Worker and Reviewer are this profile's engagement frames",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FEngagement%20frame",
          "start_line": 339
        }
      ],
      "key": "engagement_frame",
      "label": "Engagement frame"
    },
    {
      "conditions": [
        "Needed by one engagement evaluation and activated."
      ],
      "definition": "A Product, requirement, design, identity, release, domain, implementation, test, operational, historical or capability frame used by an engagement evaluation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 348,
          "quote": "A specialist frame is an activated Product, requirement, design, identity,\nrelease, domain, implementation, test, operational, historical or\ncapability frame that one engagement evaluation needs.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FSpecialist%20frame",
          "start_line": 346
        }
      ],
      "key": "specialist_frame",
      "label": "Specialist frame"
    },
    {
      "conditions": [],
      "definition": "A reusable evaluation-family archetype naming a recurring distinction. A project instantiates it where material, obtains a capable authority's determination of non-materiality for the exact outcome, or retains explicit coverage residuals. An archetype does not select a carrier, component, actor, architecture, owner or implementation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 360,
          "quote": "A generic specialist-frame family is a reusable evaluation-family archetype\nof this profile (§11). It names a recurring distinction that a project\neither instantiates where material, has capable authority establish as\nnon-material for the governed outcome, or keeps as an explicit coverage\nresidual",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FGeneric%20specialist-frame%20family",
          "start_line": 356
        }
      ],
      "key": "generic_specialist_family",
      "label": "Generic specialist-frame family"
    },
    {
      "conditions": [],
      "definition": "Testing frame, authoritative Product path and material combinatorial complexity are tier-2 terms owned and defined by ASSURANCE §7. This profile imports those meanings without additions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 373,
          "quote": "Testing frame, authoritative Product path and material combinatorial\ncomplexity are tier-2 terms defined in ASSURANCE §7. This profile uses them\nas defined there and adds nothing to them",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FTerms%20owned%20by%20ASSURANCE",
          "start_line": 370
        }
      ],
      "key": "assurance_owned_terms",
      "label": "ASSURANCE-owned terms"
    },
    {
      "conditions": [],
      "definition": "The engagement frame selecting or confirming bounded activation configuration and consuming closed Worker and Reviewer results under existing project decision authority. It holds the complete Product view and current MVP or release mandate needed for priority, disposition and selection of the next authorised action; this is not possession of the whole workspace.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 382,
          "quote": "Executive is this profile's label for the frame that selects or confirms\nthe bounded activation configuration and consumes closed Worker and\nReviewer results under existing project decision authority.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FExecutive",
          "start_line": 377
        }
      ],
      "key": "executive",
      "label": "Executive"
    },
    {
      "conditions": [
        "Activated as a frame under the governing work relation."
      ],
      "definition": "The constructor role of ACTIVATION §1, owning bounded construction and self-review within its exact intake through inherited operation authority. Writer is its specialisation for documents and records.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 396,
          "quote": "Worker is this profile's label for the constructor role of ACTIVATION §1\nactivated as a frame. It owns construction and self-review inside its exact\nintake, through the operation authority inherited from the governing work\nrelation.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FWorker",
          "start_line": 392
        },
        {
          "end_line": 768,
          "quote": "It allocates construction to the Worker frame, specialised as Writer for\ndocuments and records",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F7.%20Non-hierarchical%20frame%20configuration%2FThe%20executive%20configuration",
          "start_line": 767
        }
      ],
      "key": "worker",
      "label": "Worker / Writer"
    },
    {
      "conditions": [
        "Separately activated for the required independent assessment."
      ],
      "definition": "An independent live-surface evaluation frame consumed by the assessment relation of ACTIVATION §1 and governed by EVALUATION independence, traceability, assurance-boundary and qualification-freeze law. It evaluates one exact subject and returns a closed evaluation with evidence-bound technical triage when findings exist.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 405,
          "quote": "Reviewer is this profile's label for the independent live-surface\nevaluation that the assessment relation of ACTIVATION §1 consumes, governed\nby EVALUATION §3 (independence and traceability) and EVALUATION §1 and §7\n(assurance boundary and qualification freeze), activated as a frame. It\nevaluates one exact subject and returns a closed result, with evidence-bound\ntechnical triage when a finding exists.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FReviewer",
          "start_line": 400
        }
      ],
      "key": "reviewer",
      "label": "Reviewer"
    },
    {
      "conditions": [],
      "definition": "A Reviewer's assessment of one finding against the exact evaluated claim and basis. Its supportable payload comprises affected claim, observed failure, severity, causal assessment and confidence, blast radius, affected users/paths/relations, available workaround or containment, repair complexity, regression risk, material dependencies, residual uncertainty and evidence that would reduce uncertainty. Confidence is a quantified assurance claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 419,
          "quote": "Technical triage is the Reviewer's assessment of one finding against the\nexact evaluated claim and basis. Where admissible evidence and the actor's\ncapability envelope support it, the triage records",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FTechnical%20triage%2C%20severity%2C%20priority%20and%20boundary%20effect",
          "start_line": 411
        }
      ],
      "key": "technical_triage",
      "label": "Technical triage"
    },
    {
      "conditions": [],
      "definition": "Severity is the Reviewer's grade of consequence if a finding manifests. Priority is the Executive's ordering of response against complete Product outcome, likelihood, exposure, current MVP/release mandate, reversibility, dependencies, cost of delay and available capacity. They remain distinct from each other, frame results and current-boundary effect.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 434,
          "quote": "Severity grades the consequence if the finding manifests. Priority orders\nthe response relative to the complete Product outcome, likelihood and\nexposure, the current MVP or release mandate, reversibility, dependencies,\ncost of delay and available capacity. The Reviewer grades severity; the\nExecutive assigns priority",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FTechnical%20triage%2C%20severity%2C%20priority%20and%20boundary%20effect",
          "start_line": 430
        }
      ],
      "key": "severity_and_priority",
      "label": "Severity and priority"
    },
    {
      "conditions": [],
      "definition": "The Executive's recorded determination that a finding blocks the current promotion boundary, requires narrowing it, or may remain an explicit residual. This is a decision projection with no core value of its own, not a frame result or disposition, and it decides nothing by itself.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 456,
          "quote": "Current-boundary effect is the Executive's recorded determination of what\none finding does to the current promotion boundary: it blocks it, requires\nnarrowing it, or may remain an explicit residual. It is a decision\nprojection, a state this profile declares, not a result and not a\ndisposition (§8): it maps to no core value of its own and decides nothing\nby itself.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FTechnical%20triage%2C%20severity%2C%20priority%20and%20boundary%20effect",
          "start_line": 451
        }
      ],
      "key": "current_boundary_effect",
      "label": "Current-boundary effect"
    },
    {
      "conditions": [
        "Exists only after successful Worker activation."
      ],
      "definition": "The Worker's closed output to its declared consumer, the Executive in the coordinated branch. Its five construction-availability values refine the predicate 'a candidate is available': candidate_ready, refused, incomplete, re_entry_requested(authority), and re_entry_requested(basis). They are carriers, not new dispositions, assessment or acceptance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 474,
          "quote": "A work result is the Worker's closed output to its declared consumer; in\nthe coordinated branch that consumer is the Executive. It exists only after\na successful Worker activation.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FWork%20result",
          "start_line": 472
        }
      ],
      "key": "work_result",
      "label": "Work result"
    },
    {
      "conditions": [],
      "definition": "An activation-level refusal carrying its cause and the core value assigned by REFERENCE_FRAME §5. It returns to assigning authority or the declared result carrier and creates neither a Worker activation nor a Worker result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 478,
          "quote": "An `activation_refusal`, with the cause and\ncore value that\n[REFERENCE_FRAME §5](REFERENCE_FRAME.md#5-method-functions) gives it,\nreturns to the assigning authority or declared result carrier and creates\nneither a Worker activation nor a Worker result.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FWork%20result",
          "start_line": 474
        }
      ],
      "key": "activation_refusal",
      "label": "Activation refusal"
    },
    {
      "conditions": [],
      "definition": "The exact subject identity required by transition evidence and traceability. Generic method qualification requires the construction result to be frozen before material reference exposure; elsewhere an immutable identity or equivalent exact-subject relation stabilises the subject sufficiently for the assessment. The profile introduces no lifecycle state named frozen.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 536,
          "quote": "An exact candidate is the subject identity that the transition evidence of\nACTIVATION §7 and the traceability of EVALUATION §3 require.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FExact%20candidate",
          "start_line": 529
        }
      ],
      "key": "exact_candidate",
      "label": "Exact candidate"
    },
    {
      "conditions": [],
      "definition": "The Product-owned Project Reference-Frame Basis projects existing owner decisions and records the configuration's material sources. A baseline-adoption projection consumes that basis and, where it adopts the profile, records selected mapping, exact outcome, actor envelopes, evidence coordinates and revision conditions in addition to the Product binding; it is neither a second basis nor a source of authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 546,
          "quote": "A baseline-adoption projection consumes the Product-owned Project\nReference-Frame Basis of PRODUCT_DEFINITION §7. Where that basis adopts\nthis profile, the projection records the selected profile mapping, exact\noutcome, actor envelopes, evidence coordinates and revision conditions\nneeded in addition to the Product binding (§16). It is not a second\nframe-basis definition and mints none of the authority it projects",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F5.%20Profile%20terms%2FBaseline-adoption%20projection",
          "start_line": 540
        }
      ],
      "key": "product_basis_and_adoption_projection",
      "label": "Product basis and baseline-adoption projection"
    },
    {
      "conditions": [],
      "definition": "A bounded attention procedure over U, every known material evaluation not closed on the current basis, and finite dependency-ready activation subsets M. It tracks the frontier and closed-result ledger, not every evaluator's undocumented working context.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 598,
          "quote": "U0 = every known material evaluation not closed on the current basis\n\nwhile U is non-empty:\n  select a finite dependency-ready subset M that fits the assigned actors\n  activate each member of M against the exact outcome and basis",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F6.%20Executive%20attention%2C%20evaluation%20and%20action%2FAttention%20cycle",
          "start_line": 594
        }
      ],
      "key": "attention_cycle",
      "label": "Attention cycle"
    },
    {
      "conditions": [],
      "definition": "Five checks revalidated before activation and disposition: outcome lock, basis lock, Product-role lock, authority lock, and coverage-and-return lock. Their failed cases inherit the owning law's value or move; this profile adds none.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 675,
          "quote": "Before activation and before disposition, the Executive revalidates five\nlocks",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F6.%20Executive%20attention%2C%20evaluation%20and%20action%2FDrift%20locks",
          "start_line": 666
        }
      ],
      "key": "drift_locks",
      "label": "Drift locks"
    },
    {
      "conditions": [],
      "definition": "The basis of one Product or an explicit directed Product chain records distinct roles for mutable Source Project, current Product Definition, exact candidate checkpoint, Release Cut, Product, Install, Artifact, Development Product, dependent Product and composition edge. Every Development Product role binds one exact underlying Install.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 700,
          "quote": "A governed outcome may concern one Product or an explicit directed chain of\nProducts. Its basis records the distinct role of every mutable Source\nProject, current Product Definition, exact candidate checkpoint, Release\nCut, Product, Install, Artifact, Development Product, dependent Product and\ncomposition edge. Each Development Product role binds one exact underlying\nInstall identity.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F6.%20Executive%20attention%2C%20evaluation%20and%20action%2FProduct-chain%20basis",
          "start_line": 695
        }
      ],
      "key": "product_chain_basis",
      "label": "Product-chain basis"
    },
    {
      "conditions": [],
      "definition": "A task-selected configuration assigning construction to Worker/Writer, required assessment to Reviewer, and coordination across tasks and granted disposition to Executive. It fits work where bounded change and delivery across successive tasks need separate attention; it is not the method's default or a role inventory all work requires.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 775,
          "quote": "It is\none configuration, selected where it fits the task, not an inventory of\nroles that all work needs.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F7.%20Non-hierarchical%20frame%20configuration%2FThe%20executive%20configuration",
          "start_line": 770
        }
      ],
      "key": "executive_configuration",
      "label": "Executive configuration"
    },
    {
      "conditions": [],
      "definition": "Three distinct structures used by the configuration: authority precedence determines which existing surface may select work, admit configuration, dispose results or require re-entry; temporal and evidence flow carries activation packets and closed results; frame topology records disjointness, overlap, conjunction, translation or composition. Evaluation independence and Reviewer assurance independence are separate activation relations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 737,
          "quote": "frame topology records disjointness, overlap, conjunction, translation\n   or composition among the evaluations actually used (REFERENCE_FRAME §7),\n   while evaluation independence and Reviewer assurance independence stay\n   separate activation relations.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F7.%20Non-hierarchical%20frame%20configuration",
          "start_line": 734
        }
      ],
      "key": "configuration_relation_structures",
      "label": "Configuration relation structures"
    },
    {
      "conditions": [],
      "definition": "The profile's selected construction strategy: the smallest real runnable path from a supported Product entry to a material outcome through selected composition, established early and widened in bounded increments. The rationale is early end-to-end feedback at the cost of later widening, without claiming superiority over lawful strategies of other configurations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 879,
          "quote": "The Executive sequences delivery around a steel thread: the smallest real,\nrunnable path from a supported Product entry to a material outcome through\nthe selected composition.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F8.%20Derived%20Executive%20frame%2FSteel-thread%20delivery",
          "start_line": 873
        }
      ],
      "key": "steel_thread",
      "label": "Steel-thread delivery"
    },
    {
      "conditions": [
        "Resolved in urn:stdo:bounded-context:reference-frame-evaluation under the selected basis."
      ],
      "definition": "Product family: evaluates whether one exact current Product claim, outcome, boundary and lifecycle govern the subject without downstream reinterpretation, using current Intent, Product, requirements, acceptance meaning and exact coordinates. Product and requirement authority retain meaning and acceptance; output is bounded evaluation and evidence only. Immediate falsifier: design, code, tests, predecessor behaviour or local convention changes Product meaning or substitutes another Product subject.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1019,
          "quote": "Product and requirement authority keep meaning and acceptance. The frame returns only a bounded evaluation result and evidence.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1019
        }
      ],
      "key": "product_evaluation_family",
      "label": "Product evaluation family"
    },
    {
      "conditions": [
        "Resolved in the reference-frame-evaluation bounded context."
      ],
      "definition": "Product Composition family: evaluates an exact directed Product relation preserving source/target roles, Product Definition, Release Cut, Product and Install identities, Development Product role bindings, contracts, authority, lifecycle, evidence boundary and invalidation law. A chain uses bounded edge activations and declared conjunction. Each Product retains meaning; cited authority/contracts own the edge; output is evaluation evidence only. Falsifiers include connectivity or builder convenience creating/changing composition, confusing builder with authored Product, or one node silently redefining another.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1020,
          "quote": "A chain is evaluated through bounded edge activations and a declared conjunction.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1020
        }
      ],
      "key": "product_composition_family",
      "label": "Product Composition family"
    },
    {
      "conditions": [
        "Resolved in the reference-frame-evaluation bounded context."
      ],
      "definition": "Design family: evaluates whether accepted structural HOW satisfies material constitutional WHAT, closes required design relations and preserves owners across affected topology. Accepted design under Product and requirements owns structure; output may identify satisfaction, contradiction or design re-entry gap, never invent Product truth. Falsifiers: implementation precedent resolves open material design decisions, design creates Product meaning, or material relations/competing structures remain undeclared.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1021,
          "quote": "The frame may identify satisfaction, contradiction or a design re-entry gap; it cannot invent Product truth.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1021
        }
      ],
      "key": "design_family",
      "label": "Design family"
    },
    {
      "conditions": [
        "Resolved in the reference-frame-evaluation bounded context."
      ],
      "definition": "Design Component family: evaluates one bounded component and direct causal dependency cone against parent contract, internal relations, sibling seams and required outputs. Accepted design owns only its bounded composition decision; parent, sibling, Product, requirement and runtime owners retain theirs. Falsifiers: omitted material far-side seam, absorbed sibling/parent decision, or local closure with unresolved direct composition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1022,
          "quote": "The accepted design boundary owns only its bounded composition decision. Parent, sibling, Product, requirement and runtime owners keep their relations.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1022
        }
      ],
      "key": "design_component_family",
      "label": "Design Component family"
    },
    {
      "conditions": [
        "Resolved in the reference-frame-evaluation bounded context."
      ],
